from typing import List

def rankTeams(votes: List[str]) -> str:
    teams = {team: [0] * len(votes[0]) for team in votes[0]}
    for vote in votes:
        for i, team in enumerate(vote):
            teams[team][i] -= 1
    return ''.join(sorted(votes[0], key=lambda team: (teams[team], team)))
